tool_input.command:
cat > job_config.json <<EOF
{
  "name": "${MLPAB_DATABRICKS_PREFIX}_recommendations_job",
  "tasks": [
    {
      "task_key": "compute_recommendations",
      "spark_python_task": {
        "python_file": "/tmp/${MLPAB_DATABRICKS_PREFIX}_recommendations.py"
      },
      "existing_cluster_id": "${MLPAB_DATABRICKS_DEFAULT_CLUSTER_ID}",
      "libraries": [],
      "timeout_seconds": 3600
    }
  ]
}
EOF
databricks jobs create --json @job_config.json

cat > dlt_pipeline.json <<EOF
{
  "name": "${MLPAB_DATABRICKS_PREFIX}_recommendations_pipeline",
  "storage": "/tmp/${MLPAB_DATABRICKS_PREFIX}_recommendations",
  "configuration": {
    "spark.sql.shuffle.partitions": "2"
  },
  "clusters": [
    {
      "label": "default",
      "autoscale": {
        "min_workers": 1,
        "max_workers": 2,
        "mode": "ENHANCED"
      }
    }
  ],
  "libraries": [
    {
      "notebook": {
        "path": "/tmp/${MLPAB_DATABRICKS_PREFIX}_recommendations"
      }
    }
  ],
  "continuous": false,
  "development": true,
  "photon": false,
  "edition": "ADVANCED",
  "channel": "CURRENT"
}
EOF

databricks pipelines create --json @dlt_pipeline.json
